const html = $input.first().json.data;
const cheerio = require('cheerio');
const $ = cheerio.load(html);

const pages = [
  'https://www.chandigarhdentist.com',
  'https://www.chandigarhdentist.com/about',
  'https://www.chandigarhdentist.com/services',
  'https://www.chandigarhdentist.com/treatments',
  'https://www.chandigarhdentist.com/testimonials',
  'https://www.chandigarhdentist.com/contact',
  'https://www.chandigarhdentist.com/faq'
];

return pages.map(url => ({ json: { url } }));

const html = $json.data || '';
const url = $json.url || '';

// Simple text extraction
const text = html
  .replace(/<script[^>]*>.*?<\/script>/gs, '')
  .replace(/<style[^>]*>.*?<\/style>/gs, '')
  .replace(/<nav[^>]*>.*?<\/nav>/gs, '')
  .replace(/<footer[^>]*>.*?<\/footer>/gs, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 3000);

const categoryMap = {
  'about': 'about_doctor',
  'services': 'services',
  'treatments': 'treatments',
  'testimonials': 'testimonials',
  'contact': 'clinic_info',
  'faq': 'faqs'
};

let category = 'general';
for (const [key, cat] of Object.entries(categoryMap)) {
  if (url.includes(key)) { category = cat; break; }
}

return [{ json: { url, category, content: text, title: `${category} — ${url}`, timestamp: new Date().toISOString() } }];
